'use strict';const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const repo=path.resolve(__dirname,'../../..'),name=process.argv[2];assert.match(name||'',/^[a-z0-9-]+$/);const out=path.join(repo,'.artifacts/deep-audit-question-delivery',name);assert.ok(!fs.existsSync(out));
(async()=>{const api=await import(require('node:url').pathToFileURL(path.join(repo,'scripts/deep-audit-question-delivery-patch.mjs')));fs.mkdirSync(out,{recursive:true});const data={};for(const [label,pkg,fn] of [['question','dsh-client-ui-user-questions',api.deriveQuestionDeliverySource],['gateway','dsh-api-gateway',api.deriveGatewayDeliverySource]]){const input=fs.readFileSync(path.join(repo,'node_modules/@deepseek-ai',pkg,'lib/client.js'),'utf8'),result=fn(input);fs.writeFileSync(path.join(out,label+'.js'),result,{flag:'wx'});data[label]={input:crypto.createHash('sha256').update(input).digest('hex'),output:crypto.createHash('sha256').update(result).digest('hex')}}fs.copyFileSync(path.join(repo,'scripts/deep-audit-question-delivery-patch.mjs'),path.join(out,'producer.mjs'));fs.writeFileSync(path.join(out,'hashes.json'),JSON.stringify(data,null,2));console.log(JSON.stringify({out,...data}));})().catch(e=>{console.error(e);process.exitCode=1});
